def transform(grid):
    if not grid:
        return grid
    R = len(grid)
    if R == 0:
        return grid
    C = len(grid[0])
    bg = grid[0][0]

    # Work on a copy to preserve input integrity if needed, though ARC tasks allow in-modification
    res = [row[:] for row in grid]
    visited = [[False for _ in range(C)] for _ in range(R)]

    for r in range(R):
        for c in range(C):
            if visited[r][c]:
                continue

            val = grid[r][c]
            # Mark as visited immediately to avoid re-checking skipped cells
            visited[r][c] = True

            if val == bg or val == 0:
                continue

            # BFS to find the connected component
            comp = []
            queue = [(r, c)]
            # Note: grid[r][c] is here, but we already marked visited[r][c] in the outer loop

            # We need to ensure we only expand to neighbors of 'val'
            # Since we are iterating based on grid, we can use grid for connectivity

            idx = 0
            while idx < len(queue):
                cr, cc = queue[idx]
                idx += 1
                comp.append((cr, cc))

                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < R and 0 <= nc < C:
                        if not visited[nr][nc] and grid[nr][nc] == val:
                            visited[nr][nc] = True
                            queue.append((nr, nc))

            if comp:
                # Determine bounding box
                min_r = min(x[0] for x in comp)
                max_r = max(x[0] for x in comp)
                min_c = min(x[1] for x in comp)
                max_c = max(x[1] for x in comp)

                # Check if the component forms a solid rectangle
                is_rect = True
                for rr in range(min_r, max_r + 1):
                    for cc in range(min_c, max_c + 1):
                        if (rr, cc) not in comp:
                            is_rect = False
                            break
                    if not is_rect:
                        break

                if is_rect:
                    # Fill interior with 8
                    for rr in range(min_r + 1, max_r):
                        for cc in range(min_c + 1, max_c):
                            if res[rr][cc] == val:
                                res[rr][cc] = 8

    return res
